<script setup lang="ts">
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { http } from '@/utils/request'

type OptionChoice={name:string;price_delta:number}
type OptionGroup={name:string;required:boolean;choices:OptionChoice[]}
type Item={id:number;name:string;description?:string;image?:string;price:number;original_price?:number;stock:number;category_id?:number;option_groups?:OptionGroup[]}
type Category={id:number;name:string}
type SelectedOption={group_name:string;choice_name:string;price_delta:number}
type CartLine={key:string;menu_item_id:number;quantity:number;unit_price:number;selected_options:SelectedOption[]}

const merchant=ref<any>(null), items=ref<Item[]>([]), categories=ref<Category[]>([]), active=ref<number|undefined>(), loading=ref(false), cart=ref<Record<string,CartLine>>({}), specItem=ref<Item|null>(null), specSelections=ref<Record<string,string>>({})
const payload=(v:any)=>v?.data?.data??v?.data??v??{}
const shown=computed(()=>active.value?items.value.filter(v=>v.category_id===active.value):items.value)
const cartLines=computed(()=>Object.values(cart.value)); const count=computed(()=>cartLines.value.reduce((a,b)=>a+b.quantity,0)); const amount=computed(()=>cartLines.value.reduce((a,b)=>a+b.unit_price*b.quantity,0))
const canOrder=computed(()=>merchant.value?.is_orderable !== false)
const optionGroups=(item:Item)=>Array.isArray(item.option_groups)?item.option_groups:[]
const itemQuantity=(item:Item)=>cartLines.value.filter(line=>line.menu_item_id===item.id).reduce((sum,line)=>sum+line.quantity,0)
function selectedOptions(item:Item){return optionGroups(item).flatMap(group=>{const choice=group.choices.find(row=>row.name===specSelections.value[group.name]);return choice?[{group_name:group.name,choice_name:choice.name,price_delta:Number(choice.price_delta||0)}]:[]})}
function lineKey(item:Item,selected:SelectedOption[]){return `${item.id}:${selected.map(row=>`${row.group_name}=${row.choice_name}`).join('|')}`}
function priceOf(item:Item,selected:SelectedOption[]){return Number(item.price)+selected.reduce((sum,row)=>sum+Number(row.price_delta||0),0)}
const specPrice=computed(()=>specItem.value?priceOf(specItem.value,selectedOptions(specItem.value)):0)
async function load(id:string){loading.value=true;try{const data=payload(await http.get(`/food/merchants/${id}`)); merchant.value=data.merchant;items.value=data.menu_items||[];categories.value=data.categories||[];active.value=categories.value[0]?.id}catch(e:any){uni.showToast({title:e?.message||'菜单加载失败',icon:'none'})}finally{loading.value=false}}
function addLine(item:Item,selected:SelectedOption[],delta=1){const key=lineKey(item,selected),current=cart.value[key],next=(current?.quantity||0)+delta,total=itemQuantity(item)+delta;if(item.stock>=0&&total>item.stock)return uni.showToast({title:'库存不足',icon:'none'});if(total>99)return uni.showToast({title:'单个菜品最多 99 份',icon:'none'});if(next<=0){const copy={...cart.value};delete copy[key];cart.value=copy}else cart.value={...cart.value,[key]:{key,menu_item_id:item.id,quantity:next,unit_price:priceOf(item,selected),selected_options:selected}}}
function openItem(item:Item){if(!canOrder.value)return uni.showToast({title:'商家当前已打烊',icon:'none'});if(!optionGroups(item).length)return addLine(item,[]);specItem.value=item;const next:Record<string,string>={};optionGroups(item).forEach(group=>{if(group.required)next[group.name]=group.choices[0]?.name||''});specSelections.value=next}
function removeItem(item:Item){const line=cartLines.value.find(row=>row.menu_item_id===item.id);if(line)addLine(item,line.selected_options,-1)}
function chooseSpec(group:OptionGroup,choice:string){specSelections.value={...specSelections.value,[group.name]:choice}}
function closeSpec(){specItem.value=null;specSelections.value={}}
function confirmSpec(){if(!specItem.value)return;const missing=optionGroups(specItem.value).find(group=>group.required&&!specSelections.value[group.name]);if(missing)return uni.showToast({title:`请选择${missing.name}`,icon:'none'});addLine(specItem.value,selectedOptions(specItem.value));closeSpec()}
function checkout(){if(!canOrder.value)return uni.showToast({title:'商家当前已打烊',icon:'none'});if(!cartLines.value.length)return;const selected=cartLines.value.map(line=>({id:line.menu_item_id,quantity:line.quantity,selected_options:line.selected_options}));uni.navigateTo({url:`/pages/food/checkout?merchant=${merchant.value.id}&items=${encodeURIComponent(JSON.stringify(selected))}`})}
onLoad((q:any)=>load(String(q.id||'')))
</script>
<template><view class="menu-page"><view v-if="loading" class="state">菜单加载中…</view><template v-else-if="merchant"><view class="store"><text class="title">{{merchant.name}}</text><text>{{merchant.announcement||merchant.description||merchant.address}}</text><view><text>起送 ¥{{Number(merchant.min_order_amount||0).toFixed(0)}}</text><text>{{merchant.prepare_minutes||15}} 分钟备餐</text><text v-if="!canOrder" class="closed">当前已打烊</text></view></view><view class="content"><scroll-view scroll-y class="cats"><view :class="{active:!active}" @tap="active=undefined">全部</view><view v-for="c in categories" :key="c.id" :class="{active:active===c.id}" @tap="active=c.id">{{c.name}}</view></scroll-view><scroll-view scroll-y class="foods"><view v-if="!shown.length" class="empty">该分类暂无菜品</view><view v-for="item in shown" :key="item.id" class="food"><image v-if="item.image" :src="item.image" mode="aspectFill"/><view v-else class="food-img">餐</view><view class="info"><text class="name">{{item.name}}</text><text class="desc">{{item.description||'新鲜现做'}}</text><text class="stock" v-if="item.stock>=0">余 {{item.stock}}</text><text v-if="optionGroups(item).length" class="spec-note">可选 {{optionGroups(item).map(group=>group.name).join('、')}}</text><view class="bottom"><view><text class="price">¥{{Number(item.price).toFixed(2)}}</text><text v-if="item.original_price" class="old">¥{{Number(item.original_price).toFixed(2)}}</text></view><view class="step"><text v-if="itemQuantity(item)" @tap="removeItem(item)">−</text><text v-if="itemQuantity(item)" class="num">{{itemQuantity(item)}}</text><text v-if="optionGroups(item).length" class="spec-add" @tap="openItem(item)">选规格</text><text v-else @tap="openItem(item)">＋</text></view></view></view></view></scroll-view></view><view class="cart"><view><text class="dot">{{count}}</text><text>¥{{amount.toFixed(2)}}</text><text class="fee">另需配送费</text></view><button :disabled="!count||!canOrder" @tap="checkout">{{canOrder?'去结算':'已打烊'}}</button></view><view v-if="specItem" class="spec-mask" @tap="closeSpec"><view class="spec-sheet" @tap.stop><view class="sheet-head"><view><text class="sheet-title">{{specItem.name}}</text><text class="sheet-price">¥{{specPrice.toFixed(2)}}</text></view><text class="close" @tap="closeSpec">×</text></view><view v-for="group in optionGroups(specItem)" :key="group.name" class="spec-group"><view><text class="group-name">{{group.name}}</text><text v-if="group.required" class="required">必选</text><text v-else class="optional">可选</text></view><view class="choices"><text v-if="!group.required" :class="{selected:!specSelections[group.name]}" @tap="chooseSpec(group,'')">不选</text><text v-for="choice in group.choices" :key="choice.name" :class="{selected:specSelections[group.name]===choice.name}" @tap="chooseSpec(group,choice.name)">{{choice.name}}{{Number(choice.price_delta||0)>0?` +¥${Number(choice.price_delta).toFixed(2)}`:''}}</text></view></view><button class="spec-confirm" @tap="confirmSpec">加入购物车 · ¥{{specPrice.toFixed(2)}}</button></view></view></template></view></template>
<style scoped lang="scss">.menu-page{min-height:100vh;padding-bottom:132rpx;background:#f6f9f3}.state,.empty{padding:80rpx 20rpx;text-align:center;color:#849087}.store{padding:30rpx 32rpx;background:#fff;color:#748078;font-size:23rpx}.store .title{display:block;margin-bottom:12rpx;color:#26392f;font-size:38rpx;font-weight:800}.store view{display:flex;gap:22rpx;margin-top:15rpx;color:#4ba475;font-size:21rpx}.store .closed{color:#d86c49;font-weight:700}.content{display:flex;height:calc(100vh - 255rpx)}.cats{width:172rpx;background:#eef4ef}.cats view{padding:28rpx 14rpx;text-align:center;color:#64746b;font-size:24rpx}.cats view.active{background:#fff;color:#2d8c61;font-weight:700}.foods{flex:1;padding:18rpx 18rpx;background:#fff}.food{display:flex;gap:16rpx;padding:18rpx 0;border-bottom:1rpx solid #edf1ee}.food image,.food-img{width:132rpx;height:132rpx;flex:0 0 auto;border-radius:15rpx}.food-img{display:flex;align-items:center;justify-content:center;background:#e6f5eb;color:#5ab484;font-size:35rpx}.info{display:flex;min-width:0;flex:1;flex-direction:column}.name{font-size:28rpx;font-weight:700}.desc,.stock,.spec-note{overflow:hidden;margin-top:8rpx;color:#8a958f;font-size:21rpx;text-overflow:ellipsis;white-space:nowrap}.spec-note{color:#48956e}.bottom{display:flex;margin-top:auto;align-items:end;justify-content:space-between}.price{color:#e76843;font-size:29rpx;font-weight:800}.old{margin-left:6rpx;color:#a1aba5;font-size:19rpx;text-decoration:line-through}.step{display:flex;align-items:center;gap:12rpx;color:#279761;font-size:35rpx;font-weight:600}.num{min-width:20rpx;color:#26392f;font-size:25rpx;text-align:center}.spec-add{border-radius:22rpx;padding:5rpx 11rpx;background:#e7f6eb;color:#288959;font-size:21rpx}.cart{position:fixed;z-index:3;right:20rpx;bottom:18rpx;left:20rpx;display:flex;height:92rpx;padding-left:27rpx;align-items:center;justify-content:space-between;border-radius:48rpx;background:#263c30;color:#fff;box-shadow:0 10rpx 28rpx rgba(19,51,32,.24)}.dot{display:inline-flex;min-width:30rpx;height:30rpx;margin-right:10rpx;align-items:center;justify-content:center;border-radius:20rpx;background:#55bf7e;font-size:18rpx}.fee{margin-left:15rpx;color:#bdc9c0;font-size:19rpx}.cart button{height:92rpx;margin:0;padding:0 38rpx;border:0;border-radius:48rpx;background:#52c41a;color:#fff;font-size:27rpx}.cart button[disabled]{background:#8c9b91}.spec-mask{position:fixed;z-index:12;top:0;right:0;bottom:0;left:0;display:flex;align-items:flex-end;background:rgba(15,31,21,.48)}.spec-sheet{width:100%;max-height:78vh;overflow:auto;border-radius:32rpx 32rpx 0 0;padding:30rpx 30rpx calc(30rpx + env(safe-area-inset-bottom));background:#fff}.sheet-head{display:flex;align-items:start;justify-content:space-between}.sheet-title{display:block;color:#26392f;font-size:34rpx;font-weight:800}.sheet-price{display:block;margin-top:8rpx;color:#df6a45;font-size:27rpx;font-weight:700}.close{padding:0 10rpx;color:#8b968f;font-size:52rpx;line-height:40rpx}.spec-group{margin-top:28rpx}.group-name{color:#2b3c32;font-size:27rpx;font-weight:700}.required,.optional{margin-left:10rpx;font-size:20rpx}.required{color:#d86c49}.optional{color:#8a958f}.choices{display:flex;flex-wrap:wrap;gap:14rpx;margin-top:15rpx}.choices text{border:1rpx solid #dce7df;border-radius:12rpx;padding:13rpx 18rpx;color:#56665d;font-size:23rpx}.choices text.selected{border-color:#329565;background:#e7f6eb;color:#237b50;font-weight:700}.spec-confirm{margin-top:38rpx;border-radius:44rpx;background:#52ad75;color:#fff;font-size:28rpx}</style>
